import re
from collections import defaultdict

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.splitlines()
    sections = defaultdict(dict)
    defaults = {}
    current_section = 'DEFAULT'

    for line in lines:
        line = line.strip()
        if not line or line.startswith(';') or line.startswith('#'):
            continue

        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1].strip()
            if current_section == 'DEFAULT':
                defaults = sections[current_section]
                continue
            sections[current_section] = {}
        else:
            key, value = line.split(maxsplit=1)
            key = key.strip().lower()
            value = value.strip()

            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]

            while line.endswith('\\'):
                next_line = next((l for l in lines[lines.index(line) + 1:] if l.strip()), '').strip()
                value += '\n' + next_line

            # Resolve interpolation
            def resolve(key):
                nonlocal sections, defaults
                if key in defaults:
                    return defaults[key]
                elif key in sections[current_section]:
                    return sections[current_section][key]
                else:
                    raise KeyError(f"Key {key} not found")

            value = re.sub(r'\$\{(\w+)\}', lambda m: resolve(m.group(1)), value)
            value = re.sub(r'\$\{(\w+):(\w+)\}', lambda m: resolve(f"{m.group(1)}.{m.group(2)}"), value)

            sections[current_section][key] = value

    return {k: v for k, v in sections.items() if k != 'DEFAULT'}
