from collections import OrderedDict
from typing import Any, Callable

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float] = None):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock or (lambda: 0)
        self.cache = OrderedDict()
        self.stats = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def put(self, key: Any, value: Any) -> None:
        current_time = self.clock()
        if key in self.cache:
            self.cache.move_to_end(key)
            self.cache[key] = value
            self.cache[key]["expiry"] = current_time + self.ttl
        else:
            if len(self.cache) >= self.capacity:
                while True:
                    oldest_key = next(iter(self.cache))
                    if self.cache[oldest_key]["expiry"] > current_time:
                        break
                    del self.cache[oldest_key]
                    self.stats["expirations"] += 1
                    self.stats["misses"] += 1
            self.cache[key] = {"value": value, "expiry": current_time + self.ttl}

    def get(self, key: Any, default: Any = None) -> Any:
        current_time = self.clock()
        if key not in self.cache:
            self.stats["misses"] += 1
            return default
        entry = self.cache[key]
        if entry["expiry"] <= current_time:
            del self.cache[key]
            self.stats["expirations"] += 1
            self.stats["misses"] += 1
            return default
        self.cache.move_to_end(key)
        entry["expiry"] = current_time + self.ttl
        self.stats["hits"] += 1
        return entry["value"]

    def __len__(self) -> int:
        current_time = self.clock()
        return sum(1 for k in self.cache if self.cache[k]["expiry"] > current_time)

    def stats(self) -> dict:
        return self.stats
