def parse_duration(s: str) -> int:
    import re

    if not s.strip():
        raise ValueError("Duration string cannot be empty or blank")

    pattern = r"(\d+)(h|m|s)"
    matches = re.findall(pattern, s.replace(" ", "").lower())

    if not matches:
        raise ValueError("Duration string must contain at least one valid unit with a number")

    units = {"h": 3600, "m": 60, "s": 1}
    total_seconds = 0

    for amount, unit in matches:
        if unit not in units:
            raise ValueError(f"Unknown unit: {unit}")
        total_seconds += int(amount) * units[unit]

    return total_seconds
