def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    nums.sort()
    result = []
    start = None

    for i in range(len(nums)):
        if start is None or nums[i] == nums[i - 1] + 1:
            start = nums[i]
        else:
            if i > 0 and nums[i - 1] - nums[i - 2] >= 2:
                result.append(f"{start}..{nums[i - 1]}")
                start = nums[i]
            else:
                result.extend(map(str, range(nums[i - 1], nums[i])))

    if start is not None:
        if len(nums) - nums.index(start) >= 2:
            result.append(f"{start}..{nums[-1]}")
        else:
            result.extend(map(str, range(start, nums[-1] + 1)))

    return ",".join(result)
